//
// The ECHO hyperspace of the Hyperspace slide as a canvas element kind: a field packed with circles, each one a space
// holding a connected graph of objects on a hexagonal lattice, with dashed bridges between spaces and the objects a
// plugin shows lit in their type's colour (studio `assets/deck/lib/substrate-view.mjs`).
//
// It is the space graph packed into many circles instead of one, so each space's graph is generated by the same
// module (`components/Graph/generator/space-graph.generator.ts`) from the field's seed and the space's index.
//
// What is NOT ported, and is read from the sidecar instead: the packing (`packages/substrate/pack.mjs`) and the flow
// resolution (nearest entry, a ranked walk, a route that avoids links an earlier flow took). The sidecar records
// their output — every space's circle, and every lit object with its type and position — which is what this kind
// takes as its input. A port would replace `spaces` and `lit` with a second seed; the drawing would not change.
//

import './theme.css';

import * as Schema from 'effect/Schema';
import React from 'react';

import { type ElementKindSpec, type NodeViewProps, defaultPorts, kindData } from '@dxos/react-ui-canvas';
import { type Node, type Port, Scene } from '@dxos/scene';

import { layout, rng, subgraph } from '../../components/Graph/generator/space-graph.generator.ts';
import { graphFields } from '../../components/Graph/index.ts';
import { TONES, toneValue } from './FeedCard.tsx';
import { type Circle, type LitPoint, packSpaces, parseLit, parseSpaces } from './substrate-packing.ts';

/** A packed space, as a fraction of the field's own box so it scales with the node. */
const Space = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
  /** The radius, as a fraction of the field's width. */
  r: Schema.Number,
});

/** An object a plugin flow lights up, as a fraction of the field's box, in its type's colour. */
const Lit = Schema.Struct({
  x: Schema.Number,
  y: Schema.Number,
  tone: Schema.optional(Schema.Literals(TONES)),
});

export const substrateFields = {
  ...graphFields,
  /**
   * The packed spaces, in packing order: the CACHED result of the packing, not its definition. A drawing written
   * down as text keeps the rule (the four fields below) and loses this, and the field packs itself again — which
   * is the spec's "the rule is authoritative, geometry is a cached projection", for the one kind that needed it.
   */
  spaces: Schema.optional(Schema.Union([Schema.Array(Space), Schema.String]).annotate({ title: 'Spaces' })),
  /** How many spaces the field packs when it has no `spaces` of its own. */
  spaceCount: Schema.optional(
    Schema.Number.check(Schema.isInt(), Schema.isBetween({ minimum: 1, maximum: 64 })).annotate({
      title: 'Spaces',
    }),
  ),
  /** The smallest and largest a packed space may be, in scene units. */
  rmin: Schema.optional(Schema.Number.annotate({ title: 'Min radius' })),
  rmax: Schema.optional(Schema.Number.annotate({ title: 'Max radius' })),
  /** Clearance between two packed spaces, and between a space and the field's edge, in scene units. */
  gap: Schema.optional(Schema.Number.annotate({ title: 'Gap' })),
  /** The objects the plugin flows reach, drawn lit. Text or a list, as {@link substrateFields.spaces} is. */
  lit: Schema.optional(Schema.Union([Schema.Array(Lit), Schema.String]).annotate({ title: 'Lit objects' })),
  /** How many of the closest pairs of spaces are bridged. */
  bridges: Schema.optional(Schema.Number.check(Schema.isInt()).annotate({ title: 'Bridges' })),
  /**
   * The subgraph a space lights up, as a rule rather than a list of points: which space (its place in the packing),
   * which object it grows from, and how many hops out the colour reaches. The walk is over the graph this seed
   * produces, so the same objects light up after the field re-packs itself.
   */
  rootSpace: Schema.optional(Schema.Number.check(Schema.isInt()).annotate({ title: 'Lit space' })),
  root: Schema.optional(Schema.Number.check(Schema.isInt()).annotate({ title: 'Root object' })),
  depth: Schema.optional(Schema.Number.check(Schema.isInt()).annotate({ title: 'Depth' })),
  /** The colours the subgraph draws from, one per object, dealt by the field's own seed (`accent | message`). */
  tones: Schema.optional(
    Schema.Union([Schema.Array(Schema.Literals(TONES)), Schema.String]).annotate({ title: 'Subgraph tones' }),
  ),
};

/** The kind's own fields, kept under `data` (decision 21). */
export const SubstrateData = Schema.Struct(substrateFields);

export const SubstrateNode = Schema.Struct({
  ...Scene.Element2D.fields,
  type: Schema.Literal('substrate'),
  data: SubstrateData,
});

const DEFAULTS = {
  pitch: 24,
  fill: 0.55,
  extra: 0.4,
  size: 24,
  bridges: 0,
  spaceCount: 9,
  rmin: 34,
  rmax: 150,
  gap: 10,
} as const;

/** The palette a marked subgraph draws from, from either form; a name the deck does not know is dropped. */
const tonesOf = (tones: readonly string[] | string | undefined): string[] =>
  (typeof tones === 'string' ? tones.split('|').map((name) => name.trim()) : (tones ?? [])).flatMap((name) => {
    const value = toneValue(name);
    return value ? [value] : [];
  });

/** The `count` closest pairs of spaces, by the gap between their edges: what the field bridges. */
const bridgesOf = (spaces: readonly Circle[], count: number): [number, number][] =>
  spaces
    .flatMap((from, index) =>
      spaces.slice(index + 1).map((to, offset) => ({
        pair: [index, index + 1 + offset] as [number, number],
        gap: Math.hypot(to.x - from.x, to.y - from.y) - from.r - to.r,
      })),
    )
    .sort((left, right) => left.gap - right.gap)
    .slice(0, Math.max(0, count))
    .map(({ pair }) => pair);

/** The segment between two spaces, from edge to edge. */
const span = (from: Circle, to: Circle) => {
  const length = Math.hypot(to.x - from.x, to.y - from.y) || 1;
  const [unitX, unitY] = [(to.x - from.x) / length, (to.y - from.y) / length];
  return {
    x1: from.x + unitX * from.r,
    y1: from.y + unitY * from.r,
    x2: to.x - unitX * to.r,
    y2: to.y - unitY * to.r,
  };
};

export const SubstrateNodeView = ({ node }: NodeViewProps) => {
  const data = kindData(SubstrateData, node);
  if (!data) {
    return null;
  }

  const settings = { ...DEFAULTS, ...data };
  const { width, height } = node.size;
  // The stored packing where there is one, and the rule's own where there is not: fractions against the node's
  // own box either way, so the field moves and resizes with the node.
  const stored = typeof settings.spaces === 'string' ? parseSpaces(settings.spaces) : settings.spaces;
  const spaces: Circle[] = (stored?.length ? stored : packSpaces(settings, width, height)).map(({ x, y, r }) => ({
    x: x * width,
    y: y * height,
    r: r * width,
  }));
  const lit: LitPoint[] = typeof settings.lit === 'string' ? parseLit(settings.lit) : [...(settings.lit ?? [])];
  // Each space's own lattice, seeded by the field's seed and the space's place in the packing: one module, nine
  // scales. `layout` names the object radius `size`, which an element's own `size` (its frame) already takes.
  const graphs = spaces.map((space, index) =>
    layout({ x: space.x, y: space.y }, space.r, {
      ...settings,
      seed: settings.seed + index,
      size: settings.size,
    }),
  );
  // The subgraph the field marks, walked over the graph the seed produced rather than read off a list of points.
  const palette = tonesOf(settings.tones);
  const markSpace = settings.rootSpace ?? 0;
  const mark =
    palette.length && settings.depth !== undefined && graphs[markSpace]
      ? subgraph(graphs[markSpace].links, settings.root ?? 0, settings.depth)
      : undefined;
  // A colour per object, dealt once from the field's own seed: the same object keeps its colour across renders,
  // and a link takes the colour of the end it leaves.
  const marked = new Map<number, string>();
  if (mark && palette.length) {
    const random = rng(settings.seed + 977);
    for (const index of [...mark.nodes].sort((left, right) => left - right)) {
      marked.set(index, palette[Math.floor(random() * palette.length)]);
    }
  }
  return (
    <svg
      className='dx-cover overflow-visible'
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      data-testid='substrate-node'
    >
      {bridgesOf(spaces, settings.bridges).map((pair, index) => (
        <line
          key={`bridge-${index}`}
          {...span(spaces[pair[0]], spaces[pair[1]])}
          className='stroke-neutral-border'
          strokeWidth={1.4}
          strokeDasharray='5 5'
          opacity={0.7}
        />
      ))}
      {spaces.map((space, index) => {
        const { cells, nodes, links, nodeR } = graphs[index];
        const on = new Set(nodes.map((point) => `${point.x},${point.y}`));
        return (
          <g key={`space-${index}`} data-testid='substrate-space'>
            <circle
              cx={space.x}
              cy={space.y}
              r={space.r}
              className='fill-none stroke-neutral-border'
              strokeWidth={1.6}
            />
            {cells
              .filter((cell) => !on.has(`${cell.x},${cell.y}`))
              .map((cell, cellIndex) => (
                <circle
                  key={`cell-${cellIndex}`}
                  cx={cell.x}
                  cy={cell.y}
                  r={Math.max(1.1, nodeR * 0.3)}
                  className='fill-neutral-border'
                  opacity={0.3}
                />
              ))}
            {links.map(([from, to], linkIndex) => {
              // A marked link takes the colour as an attribute and drops the class: a Tailwind `stroke-*` would
              // win over it, which is how the first attempt came out grey.
              const tone = index === markSpace && mark?.links.has(linkIndex) ? marked.get(from) : undefined;
              return (
                <line
                  key={`link-${linkIndex}`}
                  x1={nodes[from].x}
                  y1={nodes[from].y}
                  x2={nodes[to].x}
                  y2={nodes[to].y}
                  className={tone ? undefined : 'stroke-neutral-border'}
                  stroke={tone}
                  strokeWidth={Math.max(1.2, nodeR * (tone ? 0.42 : 0.32))}
                  opacity={tone ? 0.9 : 0.55}
                />
              );
            })}
            {nodes.map((point, objectIndex) => {
              const tone = index === markSpace ? marked.get(objectIndex) : undefined;
              return (
                <circle
                  key={`object-${objectIndex}`}
                  cx={point.x}
                  cy={point.y}
                  r={tone ? nodeR * 1.2 : nodeR}
                  className={tone ? undefined : 'fill-neutral-border'}
                  fill={tone}
                />
              );
            })}
          </g>
        );
      })}
      {/* The lit objects sit over the lattice: a plugin's own elements, in the colour of the type that holds them. */}
      {lit.map(({ x, y, tone }, index) => (
        <circle
          key={`lit-${index}`}
          cx={x * width}
          cy={y * height}
          r={(settings.pitch * settings.size) / 100 + 1.4}
          data-testid='substrate-lit'
          fill={toneValue(tone) ?? 'var(--sd-fg)'}
        />
      ))}
    </svg>
  );
};

/**
 * A port per packed space, on both sides of the field at that space's own height: what a drawing links to when it
 * says which space a plank reads. The packing is the same function the view draws, so a port follows its space
 * rather than naming a point someone has to keep in step. The defaults stay beside them, so the field can still be
 * tied to by its own edges.
 */
const substratePorts = (node: Node): readonly Port[] => {
  const data = kindData(SubstrateData, node);
  if (!data) {
    return defaultPorts;
  }
  const settings = { ...DEFAULTS, ...data, seed: data.seed ?? 0 };
  const { width, height } = node.size;
  const stored = typeof settings.spaces === 'string' ? parseSpaces(settings.spaces) : settings.spaces;
  // Both forms are fractions of the field's own box, which is what a port's offset along a side already is.
  const spaces: readonly Circle[] = stored?.length ? stored : packSpaces(settings, width, height);
  return [
    ...spaces.flatMap((space, index) => [
      { id: `space-${index}`, side: 'w' as const, offset: space.y },
      { id: `space-${index}-e`, side: 'e' as const, offset: space.y },
    ]),
    ...defaultPorts,
  ];
};

export const substrateSpec: ElementKindSpec = {
  // Five ports a side: a true middle to tie a trunk to, and room either side of it for a fan of edges
  // that converge on one card.
  portsPerSide: 5,
  name: 'Substrate',
  icon: 'ph--circles-three--regular',
  key: 'B',
  schema: SubstrateNode,
  component: SubstrateNodeView,
  create: ({ id, z, center, size }) => ({ type: 'substrate', id, z, center, size, data: { seed: 29 } }),
  // Nominal units (one unit is the major grid cell, 48px): the deck's 812 x 820 field, give or take.
  defaultSize: { width: 17, height: 17 },
  resizable: true,
  minSize: { width: 180, height: 180 },
  ports: substratePorts,
  // The field is the shape: the kind draws every circle it holds.
  bare: true,
};
